class Component extends DCLogic {
 constructor(p){super(p);this.state={query:'',filter:'all',all:false,sel:'',applied:{}};}
 renderVals(){const s=this.state;const roles=ROLES.filter(x=>x.status==='Опубликовано'&&(s.filter==='all'||(s.filter==='online'?x.format.includes('Онлайн'):x.regularity===s.filter))&&(`${x.title} ${x.program} ${x.task}`).toLowerCase().includes(s.query.toLowerCase()));const selected=ROLES.find(x=>x.id===s.sel)||ROLES[0];return {current:ROLES[0],selected,detail:!!s.sel,openCurrent:()=>this.setState({sel:'assistant'}),close:()=>this.setState({sel:''}),query:s.query,search:e=>this.setState({query:e.target.value,all:false}),filters:[['all','Все'],['Регулярно','Регулярно'],['Разово','Разово'],['online','Онлайн']].map(([id,title])=>({title,cls:'chip'+(s.filter===id?' is-on':''),pick:()=>this.setState({filter:id,all:false})})),roles:(s.all?roles:roles.slice(0,3)).map((r,i)=>({...r,art:'art '+['art-o','art-b','art-y'][i%3],pick:()=>this.setState({sel:r.id})})),empty:!roles.length,hasMore:!s.all&&roles.length>3,showAll:()=>this.setState({all:true}),reset:()=>this.setState({query:'',filter:'all'}),canApply:!s.applied[selected.id],applied:!!s.applied[selected.id],apply:()=>this.setState({applied:{...s.applied,[selected.id]:true}})};}
}
